import * as d3 from 'd3'
import type {LoopNode, NodeKind} from './types'
import {canonicalStatus, type StatusVocab} from './colors'

export const fmtInt = d3.format(',d')
export const fmtCompact = d3.format('.3~s')
export const fmtChars = (n: number | undefined): string =>
	n === undefined ? '—' : `${fmtInt(n)} chars`
export const fmtTokens = (n: number | undefined): string =>
	n === undefined ? '—' : `≈${fmtInt(n)} tokens (est.)`
export const fmtTime = (iso: string | undefined): string => {
	if (!iso) return '—'
	const d = new Date(iso)
	return Number.isNaN(d.getTime())
		? iso
		: d
				.toISOString()
				.replace('T', ' ')
				.replace(/\.\d+Z$/, 'Z')
}

/** Format an ISO timestamp relative to the start of a run (e.g. "+09:17"). */
export function fmtElapsed(
	iso: string | undefined,
	originIso: string | undefined,
): string | null {
	if (!iso || !originIso) return null
	const t = Date.parse(iso)
	const t0 = Date.parse(originIso)
	if (!Number.isFinite(t) || !Number.isFinite(t0)) return null
	const diffSec = Math.max(0, Math.round((t - t0) / 1000))
	const mins = Math.floor(diffSec / 60)
	const secs = diffSec % 60
	return `+${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
}

/** Colour vocabulary lives in `./colors` behind a domain-checked union; format.ts keeps text/glyph concerns only. */
export {agentColor, stageColor, statusColor} from './colors'

const STATUS_GLYPHS: Readonly<Record<StatusVocab, string>> = {
	completed: '✓',
	in_progress: '▶',
	blocked: '⏸',
	failed: '✗',
	todo: '○',
}

/** Status glyph for any dataset spelling — same synonym table as statusColor, so glyph and colour agree. */
export function statusGlyph(status: string | undefined): string {
	const canonical = canonicalStatus(status)
	return canonical ? STATUS_GLYPHS[canonical] : '○'
}

export const KIND_LABEL: Record<NodeKind, string> = {
	project: 'project',
	thread: 'thread',
	turn: 'turn',
	'user-message': 'user message',
	reasoning: 'reasoning',
	text: 'assistant text',
	'tool-call': 'tool call',
	'tool-result': 'tool result',
	task: 'task',
	'worker-thread': 'worker thread',
	wake: 'wake',
	phase: 'phase (documented)',
}

/** Kinds whose text is code/JSON — rendered monospace in the info panels' text blocks. */
export function isCodeLike(node: LoopNode): boolean {
	if (node.kind === 'tool-call' || node.kind === 'tool-result') return true
	const t = node.meta?.fullText ?? node.meta?.excerpt ?? ''
	return /^\s*[[{]/.test(t)
}

export function stageLabel(stage: string): string {
	return stage.startsWith('tool:') ? `tool: ${stage.slice(5)}` : stage
}

/** Human-readable display label for an agent identifier (canonical keys remain intact for colours/cost). */
export function agentDisplayName(agent: string | undefined): string {
	if (!agent) return 'Unknown'
	if (agent === 'user') return 'User'
	if (agent === 'orchestrator') return 'Orchestrator'
	if (agent === 'worker:agent') return 'Worker agent'
	if (agent.startsWith('worker:')) return `Worker · ${agent.slice(7)}`
	return agent
}

/** Format a percentage share cleanly (e.g. "98.0%" or "<0.1%"). */
export function fmtPct(part: number, total: number): string {
	if (!total || !Number.isFinite(part)) return '0%'
	const pct = (part / total) * 100
	if (pct > 0 && pct < 0.1) return '<0.1%'
	return pct >= 10 ? `${pct.toFixed(1)}%` : `${pct.toFixed(1)}%`
}

export function nodeAriaLabel(node: LoopNode): string {
	const m = node.meta
	const bits = [node.name, KIND_LABEL[node.kind] ?? node.kind]
	if (m?.agent) bits.push(m.agent)
	if (m?.chars !== undefined) bits.push(`${fmtInt(m.chars)} characters`)
	if (m?.status) bits.push(`status ${m.status}`)
	return bits.join(', ')
}
